### 2. Publisher interface (`src/ipc/trace_publisher.h`)

```cpp
#ifndef BITCOIN_IPC_TRACE_PUBLISHER_H
#define BITCOIN_IPC_TRACE_PUBLISHER_H

#include <atomic>
#include <condition_variable>
#include <memory>
#include <mutex>
#include <queue>
#include <thread>
#include <vector>

#include <capnp/message.h>
#include <capnp/serialize.h>
#include <kj/array.h>
#include <kj/io.h>

#include <ipc/tracing.capnp.h>   // generated

// Forward declaration of the low‑level I/O worker.
class TraceIoThread;

/**
 * TracePublisher – singleton that fans out Cap’n Proto tracing events to
 * all connected subscribers.  It is lock‑free for the hot path:
 *   - subscriber count is an atomic.
 *   - publishing only pushes a pointer to a pre‑allocated Event onto a
 *     single‑producer, multiple‑consumer queue (implemented with a
 *     std::deque protected by a mutex; contention is negligible because
 *     publishing is rare compared to normal node operation).
 */
class TracePublisher final {
public:
    static TracePublisher& instance();

    /// Initialize the publisher – creates the socket/listener and starts the I/O thread.
    /// Returns false if initialization fails (e.g. cannot bind socket).
    bool Initialize(const std::string& socket_path);

    /// Shut down – closes the listener, stops the I/O thread, and drains the queue.
    void ShutDown();

    /// Publish an event.  If there are no subscribers, returns immediately
    /// with zero overhead (no allocation, no serialization).
    template<typename EventType>
    void Publish(const EventType& ev) noexcept {
        if (m_subscriber_count.load(std::memory_order_acquire) == 0) {
            return; // fast‑path: no one listening
        }

        // Serialize into a Cap’n Proto message (stack allocated).
        capnp::MallocMessageBuilder message;
        auto event = message.initRoot<Event>();
        event.set(header(EventHeader{
            .timestampUsec = GetTimeMicros(),
            .kind          = EventType::KindValue,
        }));
        event.set(EventType::capnp::Which, ev); // sets the appropriate union field

        // Serialize to a flat array (zero‑copy).
        kj::ArrayPtr<const capnp::word> words = capnp::messageToFlatArray(message);
        size_t byte_len = words.size() * sizeof(capnp::word);

        // Enqueue the serialized blob for the I/O thread.
        {
            std::lock_guard<std::mutex> lk(m_queue_mtx);
            m_outgoing.emplace_back(kj::heapArrayCopy(words.begin(), words.size()));
        }
        m_queue_cv.notify_one();
    }

    /// Called by TraceIoThread when a new client connects.
    void IncrementSubscriberCount() noexcept {
        m_subscriber_count.fetch_add(1, std::memory_order_release);
    }

    /// Called by TraceIoThread when a client disconnects.
    void DecrementSubscriberCount() noexcept {
        m_subscriber_count.fetch_sub(1, std::memory_order_acq_rel);
    }

private:
    TracePublisher() = default;
    ~TracePublisher() { ShutDown(); }

    // -----------------------------------------------------------------
    // I/O worker – runs in its own thread, accepts connections, and
    // writes serialized events to each client using writev().
    // -----------------------------------------------------------------
    friend class TraceIoThread;
    std::atomic<uint32_t> m_subscriber_count{0};
    std::mutex m_queue_mtx;
    std::condition_variable m_queue_cv;
    std::vector<kj::ArrayPtr<const capnp::word>> m_outgoing; // protected by m_queue_mtx
    std::unique_ptr<TraceIoThread> m_io_thread;
    bool m_shutting_down{false};
};

#endif // BITCOIN_IPC_TRACE_PUBLISHER_H
```

