### 3. I/O worker (`src/ipc/trace_io_thread.h`)

```cpp
#ifndef BITCOIN_IPC_TRACE_IO_THREAD_H
#define BITCOIN_IPC_TRACE_IO_THREAD_H

#include <thread>
#include <atomic>
#include <memory>
#include <vector>
#include <functional>

#if defined(_WIN32)
#include <winsock2.h>
#else
#include <sys/socket.h>
#include <sys/un.h>
#include <unistd.h>
#endif

#include "trace_publisher.h"

class TraceIoThread {
public:
    explicit TraceIoThread(TracePublisher& publisher, const std::string& socket_path);
    ~TraceIoThread();

    void Start();
    void Stop();

private:
    void Run();
    void AcceptLoop(int listen_fd);
    void ClientHandler(int client_fd);

    TracePublisher& m_publisher;
    std::string m_socket_path;
    std::thread m_thread;
    std::atomic<bool> m_running{false};

#if defined(_WIN32)
    // Named pipe handle on Windows.
    HANDLE m_pipe{INVALID_HANDLE_VALUE};
#else
    int m_listen_fd{-1};
#endif
};

#endif // BITCOIN_IPC_TRACE_IO_THREAD_H
```

**Implementation (`trace_io_thread.cpp`)**

```cpp
#include "trace_io_thread.h"
#include "trace_publisher.h"
#include <util/time.h> // GetTimeMicros()
#include <util/system.h> // File access helpers
#include <util/strencodings.h> // HexStr for debugging (optional)

#if defined(_WIN32)
#include <windows.h>
#else
#include <fcntl.h>
#endif

TraceIoThread::TraceIoThread(TracePublisher& publisher, const std::string& socket_path)
    : m_publisher(publisher), m_socket_path(socket_path) {}

TraceIoThread::~TraceIoThread() {
    Stop();
}

void TraceIoThread::Start() {
    if (m_running.exchange(true)) return;
    m_thread = std::thread(&TraceIoThread::Run, this);
}

void TraceIoThread::Stop() {
    if (!m_running.exchange(false)) return;
#if defined(_WIN32)
    if (m_pipe != INVALID_HANDLE_VALUE) {
        DisconnectNamedPipe(m_pipe);
        CloseHandle(m_pipe);
        m_pipe = INVALID_HANDLE_VALUE;
    }
#else
    if (m_listen_fd >= 0) {
        close(m_listen_fd);
        m_listen_fd = -1;
    }
#endif
    if (m_thread.joinable()) m_thread.join();
}

void TraceIoThread::Run() {
#if defined(_WIN32)
    // Create a named pipe with overlapped I/O disabled (simple blocking mode).
    m_pipe = CreateNamedPipeA(
        m_socket_path.c_str(),
        PIPE_ACCESS_OUTBOUND | FILE_FLAG_WRITE_THROUGH,
        PIPE_TYPE_BYTE | PIPE_WAIT,
        PIPE_UNLIMITED_INSTANCES,
        0, 0, 0, nullptr);
    if (m_pipe == INVALID_HANDLE_VALUE) {
        LogPrintf("TraceIoThread: Failed to create named pipe %s\n", m_socket_path.c_str());
        m_running = false;
        return;
    }
    while (m_running) {
        BOOL ok = ConnectNamedPipe(m_pipe, nullptr) ||
                  GetLastError() == ERROR_PIPE_CONNECTED;
        if (!ok) {
            LogPrintf("TraceIoThread: ConnectNamedPipe failed (%lu)\n", GetLastError());
            break;
        }
        m_publisher.IncrementSubscriberCount();
        ClientHandler(reinterpret_cast<intptr_t>(m_pipe)); // reuse same handler
        DisconnectNamedPipe(m_pipe);
        m_publisher.DecrementSubscriberCount();
    }
#else
    // Unix domain socket
    m_listen_fd = socket(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0);
    if (m_listen_fd < 0) {
        LogPrintf("TraceIoThread: socket() failed: %s\n", strerror(errno));
        m_running = false;
        return;
    }

    unlink(m_socket_path.c_str()); // remove stale socket
    sockaddr_un addr{};
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, m_socket_path.c_str(), sizeof(addr.sun_path) - 1);
    if (bind(m_listen_fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) < 0) {
        LogPrintf("TraceIoThread: bind() failed: %s\n", strerror(errno));
        close(m_listen_fd);
        m_listen_fd = -1;
        m_running = false;
        return;
    }
    if (listen(m_listen_fd, SOMAXCONN) < 0) {
        LogPrintf("TraceIoThread: listen() failed: %s\n", strerror(errno));
        close(m_listen_fd);
        m_listen_fd = -1;
        m_running = false;
        return;
    }

    while (m_running) {
        int client_fd = accept(m_listen_fd, nullptr, nullptr);
        if (client_fd < 0) {
            if (errno == EINTR && !m_running) break;
            LogPrintf("TraceIoThread: accept() failed: %s\n", strerror(errno));
            continue;
        }
        m_publisher.IncrementSubscriberCount();
        std::thread([this, client_fd]() {
            ClientHandler(client_fd);
            close(client_fd);
            m_publisher.DecrementSubscriberCount();
        }).detach();
    }

    close(m_listen_fd);
    m_listen_fd = -1;
#endif
}

void TraceIoThread::ClientHandler(int client_fd) {
    // Simple blocking loop: wait for outgoing messages and write them.
    while (m_running) {
        kj::ArrayPtr<const capnp::word> msg;
        {
            std::unique_lock<std::mutex> lk(m_publisher.m_queue_mtx);
            m_publisher.m_queue_cv.wait(lk, [&] {
                return !m_publisher.m_outgoing.empty() || !m_running;
            });
            if (!m_running && m_publisher.m_outgoing.empty()) return;
            msg = m_publisher.m_outgoing.front();
            m_publisher.m_outgoing.erase(m_publisher.m_outgoing.begin());
        }

        // Write the raw bytes; Cap’n Proto guarantees contiguous memory.
        ssize_t total = 0;
        while (total < static_cast<ssize_t>(msg.size() * sizeof(capnp::word)) && m_running) {
#if defined(_WIN32)
            DWORD written = 0;
            BOOL ok = WriteFile(
                reinterpret_cast<HANDLE>(intptr_t(client_fd)),
                reinterpret_cast<const void*>(msg.begin() + total / sizeof(capnp::word)),
                static_cast<DWORD>(msg.size() * sizeof(capnp::word) - total),
                &written, nullptr);
            if (!ok) break;
            total += written;
#else
            ssize_t n = write(client_fd,
                              reinterpret_cast<const void*>(msg.begin() + total / sizeof(capnp::word)),
                              msg.size() * sizeof(capnp::word) - total);
            if (n <= 0) break;
            total += n;
#endif
        }
        if (total < static_cast<ssize_t>(msg.size() * sizeof(capnp::word))) {
            // Error or peer closed – break out.
            break;
        }
    }
}
